        image: { src: "/academy/tags.jpg", alt: "The Tag Library with a search box, A to Z and Most people first buttons, and a table of tags with People, What adds it, Your note and Rename and Retire buttons", caption: "The Tag Library. This sample account has not used these tags yet." },
