        image: { src: "/academy/links-forms.jpg", alt: "The Links & Forms page with a search box and sections for Offers checkout and sales links, Booking pages, Forms and Short links, each row with Copy and Open buttons", caption: "Links & Forms. A row marked off is turned off in your account." },
