        image: { src: "/academy/sales-plan.jpg", alt: "The Sales Plan with the Sales row of buttons, a weekly sales targets box with a Suggest my targets button, Build, Goals, Check-ins and Print / Share tabs, and the first Foundational sections", caption: "The Sales Plan, with Suggest my targets near the top." },
